import{_ as e,o as a,c as d,a6 as r}from"./chunks/framework.BoFLe3f3.js";const b=JSON.parse('{"title":"排障图谱","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1793422332000}'),o={name:"troubleshooting.md"};function i(s,t,n,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="排障图谱" tabindex="-1">排障图谱 <a class="header-anchor" href="#排障图谱" aria-label="Permalink to &quot;排障图谱&quot;">​</a></h1><p>从症状出发，沿着决策树走到根因，再跳进对应实验与章节。每条路径都对应一个可复现的故障实验。</p><h2 id="渲染一致性-hydration-mismatch" tabindex="-1">渲染一致性：hydration mismatch <a class="header-anchor" href="#渲染一致性-hydration-mismatch" aria-label="Permalink to &quot;渲染一致性：hydration mismatch&quot;">​</a></h2><p><strong>症状</strong>：控制台报 “Hydration failed / Text content does not match server-rendered HTML”，首屏内容闪一下或文字对不上。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>首屏是否读了非确定性值（<code>Date.now</code> / <code>Math.random</code> / <code>localStorage</code> / <code>window</code>）</td><td>渲染期必须两端一致——首屏用稳定占位，把这类读取挪到挂载后</td></tr><tr><td>是否渲染了非法嵌套标签（<code>&lt;p&gt;</code> 里套 <code>&lt;div&gt;</code>）</td><td>修正嵌套结构；浏览器会「纠正」HTML，从而与客户端树对不上</td></tr><tr><td>是否按环境输出不同文案（服务端/客户端分支）</td><td>改为「先占位、挂载后再切换」的渐进式渲染</td></tr></tbody></table><p><strong>修复要点</strong>：把「客户端才知道的值」全部移出渲染期。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-hydration-mismatch">实验：复现并修复 hydration mismatch</a></li><li><a href="/nextjs-tutorial-site/chapters/03-components/advanced">组件篇 · 进阶</a></li></ul><h2 id="缓存-写入后仍是旧数据" tabindex="-1">缓存：写入后仍是旧数据 <a class="header-anchor" href="#缓存-写入后仍是旧数据" aria-label="Permalink to &quot;缓存：写入后仍是旧数据&quot;">​</a></h2><p><strong>症状</strong>：写入成功后刷新仍是旧数据；内容要等很久才更新，甚至一直不更新。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>用的是 ISR（revalidate 窗口）</td><td>发布后主动调用 <code>revalidatePath</code> / <code>revalidateTag</code> 立即再生</td></tr><tr><td>用的是 <code>use cache</code> + <code>cacheTag</code></td><td>写入动作里必须 <code>updateTag</code> / <code>revalidateTag</code></td></tr><tr><td>这份读取带了会话（cookies）</td><td>它本就不该被缓存——读 cookie 即动态信号</td></tr></tbody></table><p><strong>修复要点</strong>：把「写入」与「失效」绑成一对。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-cache-stale">实验：复现并修复陈旧缓存</a></li><li><a href="/nextjs-tutorial-site/chapters/05-caching/basics">缓存篇 · 基础</a></li><li><a href="/nextjs-tutorial-site/chapters/08-rendering/internals">渲染篇 · 原理</a></li></ul><h2 id="并发-快速连点两次-结果少了-1" tabindex="-1">并发：快速连点两次，结果少了 1 <a class="header-anchor" href="#并发-快速连点两次-结果少了-1" aria-label="Permalink to &quot;并发：快速连点两次，结果少了 1&quot;">​</a></h2><p><strong>症状</strong>：快速重复提交导致丢更新、数据重复或状态错乱。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>只在前端做了 pending / 禁用按钮</td><td>只能减轻症状，挡不住重放与并发请求</td></tr><tr><td>服务端动作是 read-modify-write</td><td>串行化该动作，或改成数据库原子操作</td></tr><tr><td>业务天然可幂等（幂等键 / 唯一约束）</td><td>让重复提交产生同一结果，而不是叠加效应</td></tr></tbody></table><p><strong>修复要点</strong>：把「读—算—写」收敛成一次原子提交。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-action-race">实验：复现并修复丢失更新</a></li><li><a href="/nextjs-tutorial-site/chapters/07-server-actions/advanced">Server Actions · 进阶</a></li></ul><h2 id="即时导航-点击链接要等" tabindex="-1">即时导航：点击链接要等 <a class="header-anchor" href="#即时导航-点击链接要等" aria-label="Permalink to &quot;即时导航：点击链接要等&quot;">​</a></h2><p><strong>症状</strong>：Instant Insights 报「某次导航不够即时」，并给出修复菜单。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>目标页有阻塞式动态数据</td><td>用 Suspense 把动态区流式补齐：外壳先出，数据后到</td></tr><tr><td>是否开启 <code>cacheComponents</code> / <code>partialPrefetching</code></td><td>检查开关与 <code>use cache</code> 边界</td></tr><tr><td>数据本可在构建期或缓存期备好</td><td>前置到缓存，让导航时无需再等网络</td></tr></tbody></table><p><strong>修复要点</strong>：让「外壳即时、数据流式」成为默认。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-instant-degradation">实验：复现并修复即时导航降级</a></li><li><a href="/nextjs-tutorial-site/chapters/06-instant-navigation/advanced">即时导航 · 进阶</a></li></ul><h2 id="请求链路-中间件-代理顺序不对" tabindex="-1">请求链路：中间件/代理顺序不对 <a class="header-anchor" href="#请求链路-中间件-代理顺序不对" aria-label="Permalink to &quot;请求链路：中间件/代理顺序不对&quot;">​</a></h2><p><strong>症状</strong>：日志耗时算错，鉴权后的收尾逻辑没执行，或错误逃逸成未捕获异常。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>中间件里漏了 <code>await</code> / <code>return next()</code></td><td>后半段不会等下一层完成，after 链要么滞后要么丢失</td></tr><tr><td>在 proxy 里查库或做重活</td><td>proxy 只做乐观检查；真实鉴权必须下沉到数据层</td></tr><tr><td>matcher 误伤 <code>_next/static</code>、图片等资源</td><td>用负向匹配把非页面路径排除在链路之外</td></tr></tbody></table><p><strong>修复要点</strong>：记住洋葱模型——调用 <code>next</code> 才有 after；短路切断的是从短路层开始的下半程。</p><ul><li><a href="/nextjs-tutorial-site/labs/mini-middleware">实验：手写洋葱链与短路</a></li><li><a href="/nextjs-tutorial-site/labs/debug-middleware-after">实验：复现 after 链丢失</a></li><li><a href="/nextjs-tutorial-site/chapters/09-route-handlers/internals">Route Handlers · 原理</a></li></ul><h2 id="安全-curl-直接打-api-能拿到数据" tabindex="-1">安全：curl 直接打 API 能拿到数据 <a class="header-anchor" href="#安全-curl-直接打-api-能拿到数据" aria-label="Permalink to &quot;安全：curl 直接打 API 能拿到数据&quot;">​</a></h2><p><strong>症状</strong>：未登录也能读到受限内容，页面有 302 拦截却挡不住接口。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>鉴权只放在 proxy 或页面里</td><td>必须下沉到数据层（DAL），所有入口经它取数</td></tr><tr><td>API 与 Server Action 没有独立校验</td><td>每个入口都要 <code>requireUser</code> / <code>requireRole</code></td></tr><tr><td>直接把 JWT payload 当可信数据</td><td>先验签再读——base64 只是编码，载荷可篡改</td></tr></tbody></table><p><strong>修复要点</strong>：把鉴权收敛到唯一出口：数据访问层断言 + 每个入口独立校验。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-auth-bypass">实验：复现并修复鉴权绕过</a></li><li><a href="/nextjs-tutorial-site/chapters/11-auth-security/practice">认证与安全 · 实战</a></li><li><a href="/nextjs-tutorial-site/chapters/11-auth-security/internals">认证与安全 · 原理</a></li></ul><h2 id="渲染模式-构建后页面不更新" tabindex="-1">渲染模式：构建后页面不更新 <a class="header-anchor" href="#渲染模式-构建后页面不更新" aria-label="Permalink to &quot;渲染模式：构建后页面不更新&quot;">​</a></h2><p><strong>症状</strong>：<code>next build</code> 里某页显示 ƒ，却以为它是静态的。</p><table tabindex="0"><thead><tr><th>判定</th><th>处理</th></tr></thead><tbody><tr><td>渲染链里触达了 <code>cookies()</code> / <code>headers()</code> / <code>searchParams</code></td><td>动态信号一票否决，<code>generateStaticParams</code> 也救不回来</td></tr><tr><td>是否写了 <code>revalidate</code></td><td>写了则是 ISR（●）：静态产物 + 后台再生窗口</td></tr><tr><td>是否开启 <code>cacheComponents</code></td><td>默认转为动态/部分预渲染，静态需要显式 opt-in</td></tr></tbody></table><p><strong>修复要点</strong>：判定顺序 = 动态输入 &gt; revalidate &gt; generateStaticParams &gt; 默认。</p><ul><li><a href="/nextjs-tutorial-site/labs/debug-static-dynamic">实验：观测动态信号一票否决</a></li><li><a href="/nextjs-tutorial-site/chapters/08-rendering/internals">渲染篇 · 原理</a></li></ul>',37)])])}const p=e(o,[["render",i]]);export{b as __pageData,p as default};
